// Part: room: east ground corridor. Service passage from the hall (x51) to the dining room, pantry and powder room.
// Inner air x52..68 z51..52, floor y4, ceiling y9. The z52 row is the lane from every doorway to every other, so it
// stays clear; furniture stands on the z51 row against the north wall. Focal piece: the dark oak bench (stairs as
// seats) with a standing lantern on each fence post and a barrel with a flower pot.
// Hanging lanterns sit under the ceiling along the lane (y9) so the floor is lit at night.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  const legend = {
    "F": "dark_oak_fence", // lantern posts
    "S": ["dark_oak_stairs", { facing: "north", half: "bottom" }], // bench seats, back to the north wall
    "B": "barrel", // service barrel
    "P": "flower_pot", // on the barrel top
    "L": ["lantern", { hanging: "false" }], // standing lantern on a fence post
    "h": ["lantern", { hanging: "true" }], // hanging lantern under the ceiling
  };

  // x52..68 across (index 0 = x52), rows z51 then z52. y4: the floor furniture; the z52 lane stays clear.
  layers(g, [52, 4, 51], legend, [[
    "....F..BSSS.F....", // z51: post x56, barrel x59, bench x60..62, post x64
    ".................", // z52: lane
  ]]);
  // y5: the standing lanterns on the posts, a flower pot on the barrel
  layers(g, [52, 5, 51], legend, [[
    "....L..P....L....",
    ".................",
  ]]);
  // y9: hanging lanterns down the lane, under the ceiling
  layers(g, [52, 9, 51], legend, [[
    ".................",
    ".h....h....h...h.",
  ]]);
}

